/**
 * DANE DEMONSTRACYJNE.
 * Stawki oznaczone rateStatus: "demo" są przykładowe i NIE są oficjalnymi stawkami AV.
 * Poza trybem demo (DEMO_MODE != true) aplikacja pokazuje je jako „Stawka do ustalenia”.
 * Materiały bez targetUrl prowadzą na wewnętrzne strony demonstracyjne /demo/...
 */
type Stage = "education" | "consultation" | "transaction";
type AssetSeed = {
  slug: string; stage: Stage; type: "article" | "guide" | "webinar" | "video" | "quiz" | "calculator" | "landing" | "form" | "booking";
  title: string; description: string; body?: string; shareText: string;
};
export type ServiceSeed = {
  company: string; slug: string; name: string; category: string;
  /** ogólne, sprawdzalne fakty o samej usłudze */
  serviceFacts: string[];
  /** fakty o firmie: tylko z jej strony / wizytówki Google albo oznaczone „do potwierdzenia” */
  companyFacts: string[];
  /** tabela „my vs inni” — wiersze PRZYKŁADOWE, do potwierdzenia przez firmę */
  comparison: { label: string; us: string; others: string }[];
  /** pytanie klienta — tytuł karty usługi */
  headline: string;
  /** co partner słyszy od klienta → skojarzenie z usługą */
  hook: string;
  /** ekspert DEMO: fikcyjna osoba z wygenerowanym portretem — do podmiany na prawdziwego eksperta w panelu */
  expertName: string; expertTitle: string; expertPhotoUrl: string;
  access?: "open" | "approval_required"; sensitive?: boolean;
  clientBenefit: string; audienceShort: string; description: string;
  problems: string[]; audience: string[]; whenToRecommend: string[]; signals: string[]; arguments: string[];
  pitch: string; faq: { q: string; a: string }[]; doNotPromise: string[]; provider: string; commissionTerms: string;
  commissionModel: "fixed" | "percent" | "qualified_lead" | "custom"; commissionAmount?: number; commissionBps?: number;
  commissionCondition: string; commissionNote?: string; rateStatus: "tbd" | "demo" | "approved";
  professions: Record<string, string>; assets: AssetSeed[];
};

